SELECT id, product_id, quantity, store_id, last_restock, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity DESC, id) AS rn, SUM(quantity) OVER (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity FROM inventory WHERE last_restock <= '2023-11-04';
